xhtml:head.xhtml:script:

(function () {
  var XHTML_NS = "http://www.w3.org/1999/xhtml";

  var foreignObject =
    document.querySelector("foreignObject");

  if (!foreignObject) return;

  var root = foreignObject.firstElementChild;

  if (!root) return;

  var origCE = document.createElement.bind(document);
  var origCENS = document.createElementNS.bind(document);

  try {
    Object.defineProperty(document, "head", {
      get: function () {
        return root.querySelector("head");
      },
      configurable: true
    });

    Object.defineProperty(document, "body", {
      get: function () {
        return root.querySelector("body");
      },
      configurable: true
    });

    Object.defineProperty(document, "documentElement", {
      get: function () {
        return root;
      },
      configurable: true
    });
  } catch (e) {}

  document.createElement = function (tag, options) {
    if (typeof tag === "string") {
      return origCENS(XHTML_NS, tag, options);
    }

    return origCE(tag, options);
  };

  document.createElementNS = function (ns, name, options) {
    if (ns == null || ns === XHTML_NS) {
      return origCENS(XHTML_NS, name, options);
    }

    return origCENS(ns, name, options);
  };

  try {
    Object.defineProperty(document, "getElementById", {
      value: function (id) {
        var escaped = String(id).replace(/["\\]/g, "\\$&");
        return root.querySelector('[id="' + escaped + '"]');
      },
      configurable: true,
      writable: true
    });
  } catch (e) {}

  document.getElementsByTagName = function (tag) {
    return root.getElementsByTagNameNS(XHTML_NS, tag);
  };

  document.getElementsByTagNameNS = function (ns, tag) {
    return root.getElementsByTagNameNS(ns, tag);
  };

  document.getElementsByClassName = function (className) {
    return root.getElementsByClassName(className);
  };

  var originalQuerySelector =
    document.querySelector.bind(document);

  var originalQuerySelectorAll =
    document.querySelectorAll.bind(document);

  document.querySelector = function (selector) {
    try {
      return (
        root.querySelector(selector) ||
        originalQuerySelector(selector)
      );
    } catch (e) {
      return originalQuerySelector(selector);
    }
  };

  document.querySelectorAll = function (selector) {
    try {
      var result = root.querySelectorAll(selector);

      return result.length
        ? result
        : originalQuerySelectorAll(selector);
    } catch (e) {
      return originalQuerySelectorAll(selector);
    }
  };
})();


window.dataLayer = window.dataLayer || [];

function gtag() {
  dataLayer.push(arguments);
}

